#include <stdbool.h>
#include <string.h>

#define MAX_STACK 256

static bool opens(char c) {
    return c == '(' || c == '[' || c == '{';
}

static bool closes(char c) {
    return c == ')' || c == ']' || c == '}';
}

static char matches_opener(char c) {
    switch (c) {
        case ')': return '(';
        case ']': return '[';
        case '}': return '{';
        default: return '\0';
    }
}

bool is_balanced(const char *str) {
    bool result = false;
    size_t len = strlen(str);
    char stack[MAX_STACK];
    int top = 0;
    if (len < 2) {
        return false;
    }
    for (size_t i = 0; i < len; i++) {
        char ch = str[i];
        if (!closes(ch) && !opens(ch)) {
            continue;
        }
        if (opens(ch)) {
            if (top < MAX_STACK) {
                stack[top++] = ch;
            }
        } else {
            if (top > 0 && stack[--top] == matches_opener(ch)) {
                result = true;
            } else {
                return false;
            }
        }
    }
    if (top != 0) {
        return false;
    }
    return result;
}

